def _kaji_json_path(value: Any, path: str) -> Any:
    """Read Kaji's deliberately small JSONPath subset from a response.

    Supported paths start at ``$`` and use object fields plus optional array
    indexes (including ``[-1]``). Invalid or absent paths return ``None`` so a
    generated paginator stops safely instead of guessing a continuation.
    """
    if not path.startswith("$"):
        return None
    current = to_wire(value)
    for segment in (item for item in path[1:].split(".") if item):
        name, bracket, suffix = segment.partition("[")
        if not name or (bracket and not suffix.endswith("]")):
            return None
        if not isinstance(current, dict) or name not in current:
            return None
        current = current[name]
        if bracket:
            try:
                index = int(suffix[:-1])
            except ValueError:
                return None
            if not isinstance(current, list):
                return None
            if index < 0:
                index += len(current)
            if index < 0 or index >= len(current):
                return None
            current = current[index]
    return current


def _kaji_with_body_value(body: Any, wire_name: str, value: Any) -> Any:
    """Copy a generated JSON request body with one declared field replaced."""
    if is_dataclass(body) and not isinstance(body, type):
        for item in fields(body):
            if item.metadata.get("wire_name", item.name) == wire_name:
                return replace(body, **{item.name: value})
        raise TypeError(f"request body has no declared {wire_name!r} field")
    if isinstance(body, dict):
        return {**body, wire_name: value}
    raise TypeError("body pagination requires a generated dataclass or dictionary JSON body")


class BaseClient:
    """Configurable synchronous client for Relevate."""

    def __init__(
        self,
        base_url: str,
        *,
        api_key: str | None = None,
        bearer_token: str | None = None,
        headers: dict[str, str] | None = None,
        timeout: float = 30.0,
        max_retries: int = 2,
        retry_initial_delay: float = 0.25,
        retry_max_delay: float = 8.0,
        before_request: Callable[[dict[str, Any]], None] | None = None,
        after_response: Callable[[dict[str, Any]], None] | None = None,
        on_error: Callable[[Exception, dict[str, Any]], None] | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self.bearer_token = bearer_token
        self.headers = headers or {}
        self.timeout = timeout
        self.max_retries = max(0, max_retries)
        self.retry_initial_delay = max(0.0, retry_initial_delay)
        self.retry_max_delay = max(0.0, retry_max_delay)
        self.before_request = before_request
        self.after_response = after_response
        self.on_error = on_error

    def _request(
        self,
        method: str,
        path: str,
        *,
        query: dict[str, Any] | None = None,
        headers: dict[str, str] | None = None,
        body: Any = None,
        body_kind: str = "json",
        error_types: dict[int, tuple[type[ApiError], type[Any] | None]] | None = None,
        retryable: bool = False,
        pagination_url: str | None = None,
    ) -> Any:
        url = f"{self.base_url}{path}"
        if query:
            encoded = urlencode({key: value for key, value in query.items() if value is not None}, doseq=True)
            if encoded:
                url = f"{url}?{encoded}"
        if pagination_url is not None:
            candidate = urlsplit(urljoin(url, pagination_url))
            expected = urlsplit(url)
            if candidate.scheme != expected.scheme or candidate.netloc != expected.netloc:
                raise ValueError("pagination URL must remain on the configured API origin")
            url = candidate.geturl()
        request_headers = {"Accept": "application/json", **self.headers, **(headers or {})}
        if self.bearer_token:
            request_headers.setdefault("Authorization", f"Bearer {self.bearer_token}")
        elif self.api_key:
            request_headers.setdefault("Authorization", f"Bearer {self.api_key}")
        data = None
        if body is not None:
            if body_kind == "form":
                value = to_wire(body)
                if not isinstance(value, dict):
                    raise TypeError("form request bodies must serialize to a dictionary")
                request_headers.setdefault("Content-Type", "application/x-www-form-urlencoded")
                data = urlencode(value, doseq=True).encode("utf-8")
            elif body_kind == "binary":
                if not isinstance(body, (bytes, bytearray, memoryview)):
                    raise TypeError("binary request bodies must be bytes-like")
                request_headers.setdefault("Content-Type", "application/octet-stream")
                data = bytes(body)
            else:
                request_headers.setdefault("Content-Type", "application/json")
                data = json.dumps(to_wire(body)).encode("utf-8")
        request_context = {"method": method, "url": url, "query": query or {}, "headers": request_headers, "body": body}
        if self.before_request is not None:
            self.before_request(request_context)
        can_retry = retryable and (method.upper() in {"GET", "PUT", "PATCH", "DELETE"} or (method.upper() == "POST" and any(name.lower() == "idempotency-key" for name in request_headers)))
        for attempt in range(self.max_retries + 1):
            request = Request(url, data=data, headers=request_headers, method=method)
            try:
                with urlopen(request, timeout=self.timeout) as response:
                    status_code = response.status
                    response_headers = dict(response.headers.items())
                    if can_retry and status_code in {408, 429, 500, 502, 503, 504} and attempt < self.max_retries:
                        self._retry_delay(attempt, response_headers.get("Retry-After"))
                        continue
                    raw = response.read()
                    if self.after_response is not None:
                        self.after_response({"request": request_context, "status_code": status_code, "headers": response_headers, "body": raw})
                    if not raw:
                        return None
                    content_type = response.headers.get_content_type()
                    return json.loads(raw) if content_type == "application/json" or content_type.endswith("+json") else raw
            except HTTPError as error:
                if can_retry and error.code in {408, 429, 500, 502, 503, 504} and attempt < self.max_retries:
                    self._retry_delay(attempt, error.headers.get("Retry-After"))
                    continue
                raw = error.read()
                try:
                    response_body = json.loads(raw) if raw else None
                except json.JSONDecodeError:
                    response_body = raw.decode("utf-8", errors="replace")
                error_type, body_type = (error_types or {}).get(error.code, (ApiError, None))
                if body_type is not None and isinstance(response_body, dict):
                    response_body = body_type.from_dict(response_body)
                raised = error_type(error.code, dict(error.headers.items()), response_body)
                if self.on_error is not None:
                    self.on_error(raised, request_context)
                raise raised from error
            except URLError as error:
                if can_retry and attempt < self.max_retries:
                    self._retry_delay(attempt)
                    continue
                if self.on_error is not None:
                    self.on_error(error, request_context)
                raise
        raise RuntimeError("Kaji retry loop completed without a response")

    def _retry_delay(self, attempt: int, retry_after: str | None = None) -> None:
        try:
            server_delay = float(retry_after) if retry_after is not None else None
        except ValueError:
            server_delay = None
        delay = server_delay if server_delay is not None and server_delay >= 0 else self.retry_initial_delay * (2 ** attempt)
        time.sleep(min(delay, self.retry_max_delay))

    def _event_stream(
        self,
        method: str,
        path: str,
        *,
        query: dict[str, Any] | None = None,
        headers: dict[str, str] | None = None,
        body: Any = None,
        body_kind: str = "json",
        error_types: dict[int, tuple[type[ApiError], type[Any] | None]] | None = None,
        retryable: bool = False,
    ) -> Iterator[Any]:
        """Open an SSE response and yield decoded ``data:`` events.

        Retries are limited to establishing the connection. Once an event has
        been yielded, reconnecting is application policy: Kaji never invents a
        last-event-id or resume token.
        """
        url = f"{self.base_url}{path}"
        if query:
            encoded_query = urlencode({key: value for key, value in query.items() if value is not None}, doseq=True)
            if encoded_query:
                url = f"{url}?{encoded_query}"
        request_headers = {"Accept": "text/event-stream", **self.headers, **(headers or {})}
        if self.bearer_token:
            request_headers.setdefault("Authorization", f"Bearer {self.bearer_token}")
        elif self.api_key:
            request_headers.setdefault("Authorization", f"Bearer {self.api_key}")
        data = None
        if body is not None:
            if body_kind == "form":
                value = to_wire(body)
                if not isinstance(value, dict):
                    raise TypeError("form request bodies must serialize to a dictionary")
                request_headers.setdefault("Content-Type", "application/x-www-form-urlencoded")
                data = urlencode(value, doseq=True).encode("utf-8")
            elif body_kind == "binary":
                if not isinstance(body, (bytes, bytearray, memoryview)):
                    raise TypeError("binary request bodies must be bytes-like")
                request_headers.setdefault("Content-Type", "application/octet-stream")
                data = bytes(body)
            else:
                request_headers.setdefault("Content-Type", "application/json")
                data = json.dumps(to_wire(body)).encode("utf-8")
        context = {"method": method, "url": url, "query": query or {}, "headers": request_headers, "body": body}
        if self.before_request is not None:
            self.before_request(context)
        can_retry = retryable and (method.upper() in {"GET", "PUT", "PATCH", "DELETE"} or (method.upper() == "POST" and any(name.lower() == "idempotency-key" for name in request_headers)))
        for attempt in range(self.max_retries + 1):
            request = Request(url, data=data, headers=request_headers, method=method)
            try:
                response = urlopen(request, timeout=self.timeout)
                if self.after_response is not None:
                    self.after_response({"request": context, "status_code": response.status, "headers": dict(response.headers.items()), "body": None})
                def events() -> Iterator[Any]:
                    data_lines: list[str] = []
                    try:
                        for raw_line in response:
                            line = raw_line.decode("utf-8", errors="replace").rstrip("\r\n")
                            if line == "":
                                if data_lines:
                                    payload = "\n".join(data_lines)
                                    try:
                                        yield json.loads(payload)
                                    except json.JSONDecodeError:
                                        yield payload
                                    data_lines = []
                            elif line.startswith("data:"):
                                data_lines.append(line[5:].lstrip(" "))
                        if data_lines:
                            payload = "\n".join(data_lines)
                            try:
                                yield json.loads(payload)
                            except json.JSONDecodeError:
                                yield payload
                    finally:
                        response.close()
                return events()
            except HTTPError as error:
                if can_retry and error.code in {408, 429, 500, 502, 503, 504} and attempt < self.max_retries:
                    self._retry_delay(attempt, error.headers.get("Retry-After"))
                    continue
                raw = error.read()
                try:
                    response_body = json.loads(raw) if raw else None
                except json.JSONDecodeError:
                    response_body = raw.decode("utf-8", errors="replace")
                error_type, body_type = (error_types or {}).get(error.code, (ApiError, None))
                if body_type is not None and isinstance(response_body, dict):
                    response_body = body_type.from_dict(response_body)
                raised = error_type(error.code, dict(error.headers.items()), response_body)
                if self.on_error is not None:
                    self.on_error(raised, context)
                raise raised from error
            except URLError as error:
                if can_retry and attempt < self.max_retries:
                    self._retry_delay(attempt)
                    continue
                if self.on_error is not None:
                    self.on_error(error, context)
                raise
        raise RuntimeError("Kaji stream retry loop completed without a response")

